sn_aia_tool.script:
(function(inputs) {
    var response = {};
    var foundExactAccessLevel = false;
    if (inputs.lobby_name && inputs.lobby_name != "") {
        var directAccessLocationGr = new GlideRecordSecure('x_aleen_snguardian_access_location');
        directAccessLocationGr.addQuery('location.name', "CONTAINS", inputs.location_name);
        directAccessLocationGr.addQuery('access_level.name', "CONTAINS", inputs.lobby_name);
        directAccessLocationGr.query();
        if (directAccessLocationGr.next()) {
            response.success = true;
            response.direct_found = true;
            response.access_level_list = [];
            var accessLevel = {};
            accessLevel.access_level = directAccessLocationGr.getValue('access_level');
            accessLevel.access_level_name = directAccessLocationGr.getDisplayValue('access_level');
            response.access_level_list.push(accessLevel);
            foundExactAccessLevel = true;
        }
    }
    if (!foundExactAccessLevel) {
        var locationGr = new GlideRecordSecure('x_aleen_snguardian_location');
        locationGr.addQuery('name', "CONTAINS", inputs.location_name);
        locationGr.query();
        if (locationGr.next()) {
            response.location = locationGr.getValue('sys_id');
            response.location_name = locationGr.getValue('name');
            response.access_level_list = [];
            var accessLocationGr = new GlideRecordSecure('x_aleen_snguardian_access_location');
            accessLocationGr.addQuery('location', locationGr.getValue('sys_id'));
            accessLocationGr.query();
            while (accessLocationGr.next()) {
                var accessLevel = {};
                accessLevel.access_level = accessLocationGr.getValue('access_level');
                accessLevel.access_level_name = accessLocationGr.getDisplayValue('access_level');
                response.access_level_list.push(accessLevel);
            }
        } else {
            return JSON.stringify({
                "success": false,
                "message": "No location found with specified name"
            });
        }

        if (response.access_level_list.length == 0) {
            response.success = false;
            response.message = "No Access Levels allocated at location";
        }else{
            response.success = true;
        }
    }
    return response;

})(inputs);
